    def fmt(a):
        a = sorted(a)
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([5]), fmt([-5]), fmt([-3, -3]), fmt([-4, -1, 0, 3, 10]), fmt([-10000, 10000]), fmt([-5, -4, -3]), fmt([1, 2, 3]), fmt([0, 0, 0])]
    for n in (2, 3, 5, 8, 12, 20, 40):
        for _ in range(3):
            tests.append(fmt([rng.randint(-20, 20) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10000, 10000) for _ in range(N)]))
    tests.append(fmt([rng.randint(-10000, -1) for _ in range(N)]))
    tests.append(fmt([-10000] * (N // 2) + [10000] * (N // 2)))
    tests.append(fmt([rng.randint(0, 10000) for _ in range(N)]))
    return tests

